import unittest

from solution import chunk_records


class ChunkRecordsTests(unittest.TestCase):
    def test_full_and_partial_chunks(self):
        records = [1, 2, 3, 4, 5]
        self.assertEqual(chunk_records(records, 2), [[1, 2], [3, 4], [5]])
        self.assertEqual(records, [1, 2, 3, 4, 5])

    def test_size_larger_than_input_and_empty_input(self):
        self.assertEqual(chunk_records([1, 2], 5), [[1, 2]])
        self.assertEqual(chunk_records([], 3), [])

    def test_exact_multiple_has_all_chunks(self):
        self.assertEqual(chunk_records([1, 2, 3, 4], 2), [[1, 2], [3, 4]])
        self.assertEqual(chunk_records([1, 2, 3], 1), [[1], [2], [3]])

    def test_nested_values_are_deep_copied(self):
        first = {"items": [1]}
        second = {"items": [2]}
        records = [first, second]
        chunks = chunk_records(records, 1)
        chunks[0][0]["items"].append(9)
        self.assertEqual(records, [{"items": [1]}, {"items": [2]}])
        self.assertEqual(chunks[1], [{"items": [2]}])
        self.assertIsNot(chunks[0][0], first)
        self.assertIsNot(chunks[1][0], second)

    def test_shared_input_object_is_copied_independently_across_chunks(self):
        shared = {"nested": []}
        chunks = chunk_records([shared, shared], 1)
        self.assertIsNot(chunks[0][0], chunks[1][0])
        chunks[0][0]["nested"].append("changed")
        self.assertEqual(chunks[1][0], {"nested": []})
        self.assertEqual(shared, {"nested": []})

    def test_type_and_value_validation(self):
        for records in ((1, 2), "records", None):
            with self.subTest(records=records):
                with self.assertRaises(TypeError):
                    chunk_records(records, 1)
        for size in (True, False, 1.5, "1", None):
            with self.subTest(size=size):
                with self.assertRaises(TypeError):
                    chunk_records([], size)
        for size in (0, -1, -100):
            with self.subTest(size=size):
                with self.assertRaises(ValueError):
                    chunk_records([], size)


if __name__ == "__main__":
    unittest.main()

